/* Sectors tag every news item (field `sector`) so readers can follow fintech, health, education and other sectors across all themes. */
const SECTORS = ['Government','Fintech & payments','Health','Education','Agriculture','Social protection','Telecom','Trade & business','Energy & climate'];
const REGIONS = ['Africa','Americas','Asia-Pacific','Europe','Middle East','Global'];

const BU = 'Biometric Update';
const NEWS = [
  {id:'n43',theme:'sec',region:'Americas',country:'',sector:'Fintech & payments',type:'Guidance',trust:'official',sources:2,date:'2 Nov 2026',
   title:'Bank of Canada opens consultation on accrediting firms for open banking',
   summary:'The Bank of Canada published draft supervisory guidelines on accreditation on 2 November, the first in a series of guidelines for its supervision of participants in Canada’s Consumer-Driven Banking Framework, under which people and businesses can share their financial data with approved providers of their choice. The draft covers how the Bank plans to accredit firms that want to take part, including third parties that manage consumer consent, handle authentication information or provide or receive consumer data. The Bank will set standards for governance, risk management and operational resilience; the Department of Finance leads the regulations, which have been published in draft in the Canada Gazette. Written comments are due by 8 December 2026.',
   why:'Accreditation rules decide which fintechs and payment firms can get into an open banking system and on what terms; Canada’s draft is a fresh reference for central banks and regulators designing their own data-sharing regimes.',
   links:[['Bank of Canada launches consultation on draft supervisory guidelines related to accreditation','Bank of Canada','https://www.bankofcanada.ca/2026/11/bank-of-canada-launches-consultation-on-draft-supervisory-guidelines-related-to-accreditation/','official'],['BoC launches open banking consultation','Investment Executive','https://www.investmentexecutive.com/news/regulation/boc-launches-open-banking-consultation/','media']]},
  {id:'n44',theme:'egov',region:'Europe',country:'',sector:'Health',type:'News',trust:'media',sources:1,date:'3 Nov 2026',
   title:'Greece launches the myEOPYY app for health claims and lets patients rate the doctors they visit',
   summary:'Greece’s national health insurer EOPYY launched the myEOPYY app on 3 November, presented by Health Minister Adonis Georgiadis. The app puts each insured person’s health insurance record on their phone (cover, doctor visits, procedures, hospital stays, prescriptions and refunds), lets users photograph and upload receipts and track reimbursement claims in real time, including for children and dependants, issues an electronic ticket for collecting high-cost medicines at EOPYY pharmacies and shows average waiting times. A new provider evaluation system sends an SMS after a visit with a short questionnaire; the first phase covers contracted private specialists, diagnostic laboratories and physiotherapy centres. Ministry figures put 4.6 million social security numbers (AMKA) linked to the health insurance record, and 77% of claims in the past month arrived digitally.',
   why:'It turns a payer’s back-office record into a citizen-facing service and adds structured patient feedback on providers, a feedback loop that most national digital health programmes still lack.',
   links:[['Greece launches myEOPYY app and lets patients rate doctors','Greek City Times','https://greekcitytimes.com/2026/11/04/myeopyy-app','media']]},
  {id:'n45',theme:'dpi',region:'Asia-Pacific',country:'',sector:'Trade & business',type:'News',trust:'media',sources:1,date:'3 Nov 2026',
   title:'New Zealand trials a government-issued digital credential for businesses, the NZBN Business Passport',
   summary:'New Zealand’s Ministry of Business, Innovation and Employment (MBIE) has begun a trial of the NZBN Business Passport, a digital credential based on the New Zealand Business Number that lets a business share verified information, including proof that a person is authorised to act for it. Selected Westpac business customers hold the passport in the Govt.nz digital wallet and use it alongside a bank account credential issued by Westpac, which in September became the first New Zealand bank accredited to issue digital credentials. Biometric Update describes it as the first government-issued credential and the second accredited under the Digital Identity Services Trust Framework. MBIE says it will consider wider adoption based on feedback from businesses and banks.',
   why:'Business credentials are a practical next step after personal digital ID: they cut repeated know-your-business checks for small firms and show how a public wallet and private issuers can work under one trust framework.',
   links:[['New Zealand trials first government-issued digital credential with NZBN Business Passport',BU,'https://www.biometricupdate.com/202611/new-zealand-trials-first-government-issued-digital-credential-with-nzbn-business-passport','media']]},
  {id:'n46',theme:'dpi',region:'Africa',country:'',sector:'Government',type:'News',trust:'media',sources:2,date:'1–3 Nov 2026',
   title:'Ethiopia’s Fayda ID passes 52 million registrations as FaydaVerse studies blockchain credentials with a Korean firm',
   summary:'FaydaVerse, the state-owned company that now runs Ethiopia’s national ID programme under Ethiopian Investment Holdings, says more than 52 million people have registered for Fayda, with registration machines up from fewer than 100 to 15,000, and that 150 institutions are seeking to work with the programme. Identity verification fees of about 5 to 10 US cents per request began in August 2026; IDs stay free for citizens. On 26 October FaydaVerse signed an agreement with South Korea’s DSRV to set up a joint working group to study upgrades to the FaydaPass digital wallet and a proposed blockchain verification layer, FaydaChain, as well as a public-assistance e-voucher system that would verify beneficiaries through Fayda ID. These are studies, not deployments.',
   why:'Ethiopia is turning a fast-growing ID into a paid verification and wallet business; how it prices verification and governs reusable credentials will matter for banks, social protection and other African countries considering the same model.',
   links:[['FaydaVerse expands beyond national ID registration','Capital (Ethiopia)','https://capitalethiopia.com/?p=83820','media'],['Ethiopia’s FaydaPass digital wallet could gain blockchain-backed credentials',BU,'https://www.biometricupdate.com/202611/ethiopias-faydapass-digital-wallet-could-gain-blockchain-backed-credentials','media']]},
  {id:'n47',theme:'cyb',region:'Asia-Pacific',country:'',sector:'Government',type:'News',trust:'media',sources:2,date:'31 Oct – 3 Nov 2026',
   title:'Malaysia’s cyber agency puts MyDigital ID at the centre of national cyber defence',
   summary:'Speaking at the rawSEC MiniCon 2026 conference in Kuala Lumpur on 31 October, Dr Megat Zuhairy Megat Tajuddin, chief executive of the National Cyber Security Agency (NACSA), said digital identity must be built around trusted elements and that the Malaysia Cyber Security Strategy 2025–2030 depends on cooperation between government, business and the public. Azrin Aris, deputy chief executive of MyDigital ID Sdn Bhd, said the move from single-factor to multi-factor authentication has significantly strengthened digital identities. MyDigital ID has passed 14.1 million users and is integrated with 204 applications and websites; enrolment uses face biometrics with liveness detection, and the team says it is preparing for deepfakes, software supply-chain attacks, post-quantum cryptography and AI agents that transact for people.',
   why:'Malaysia frames digital ID as security infrastructure rather than only a convenience, a view that shapes how voluntary schemes become hard to avoid as more services depend on them.',
   links:[['Strengthening digital identity key to national cyber defence, says Nacsa chief','The Star (Malaysia), via Bernama','https://www.thestar.com.my/news/nation/2026/10/31/strengthening-digital-identity-key-to-national-cyber-defence-says-nacsa-chief','media'],['Malaysia strengthens trust in MyDigital ID as adoption expands',BU,'https://www.biometricupdate.com/202611/malaysia-strengthens-trust-in-mydigital-id-as-adoption-expands','media']]},
  {id:'n37',theme:'dpi',region:'Asia-Pacific',country:'',sector:'Fintech & payments',type:'Report',trust:'official',sources:2,date:'2 Nov 2026',
   title:'China links its digital yuan to Laos’ national payment network; AMRO sets out the lessons',
   summary:'Since 18 September 2026, Chinese visitors in Laos can pay from their e-CNY digital yuan apps by scanning the QR codes of 17 members of LAPNet, Laos’ national payment network (15 banks and two e-money providers), while Lao merchants receive kip through domestic channels. The People’s Bank of China and the Bank of the Lao PDR launched the link in Nanning. In a commentary published on 2 November, the ASEAN+3 Macroeconomic Research Office (AMRO) said it is unusual in connecting a retail central bank digital currency to a domestic payment network, and that settling in kip helps preserve monetary sovereignty. It said wider functions such as remittances and person-to-person transfers should follow only after sandbox testing, and that authorities should watch currency substitution, capital-flow rules and money-laundering risk.',
   why:'It is one of the first live links between a retail CBDC and another country’s payment switch, and the indicators AMRO proposes (active users, success rates, fees, refund and fraud rates, exchange-rate spreads) are a useful checklist for any cross-border QR link.',
   links:[['A retail CBDC meets a domestic payment network: the China–Lao PDR e-CNY Connect','ASEAN+3 Macroeconomic Research Office (AMRO)','https://www.amro-asia.org/a-retail-cbdc-meets-a-domestic-payment-network-the-china-lao-pdr-e-cny-connect','official'],['China-Laos digital payment link offers new model for cross-border transactions: AMRO','TNGlobal','https://technode.global/2026/11/02/china-laos-digital-payment-link-offers-new-model-for-cross-border-transactions-amro/','media']]},
  {id:'n38',theme:'dpi',region:'Africa',country:'',sector:'Government',type:'News',trust:'official',sources:2,date:'2 Nov 2026',
   title:'Somalia puts its Hubiye national ID verification platform into operation',
   summary:'Somalia’s National Identification and Registration Authority (NIRA) announced in late October that Hubiye, its identity verification platform, is in operation for banks, telecoms and government services. A service provider enters the holder’s national ID number, Hubiye sends a one-time password to the holder by SMS and email, and the code the holder hands over authorises a check against the national ID database. Launched in May 2025 with a certificate delivery system and the eAqoonsi digital ID app, Hubiye supported 25 integrated services, including commercial banks, serving about 1.2 million people by May 2026, according to UNDP figures cited by Biometric Update. Integration is free for now, but NIRA says some providers may eventually pay.',
   why:'Consent-based verification by one-time password is a low-cost way to make a young ID system useful to banks and agencies; whether NIRA starts charging will shape adoption before the Halmeel public service platform, planned for March 2027.',
   links:[['Somalia puts Hubiye national ID verification platform into operation',BU,'https://www.biometricupdate.com/202611/somalia-puts-hubiye-national-id-verification-platform-into-operation','media'],['Hubiye platform','National Identification and Registration Authority, Somalia','https://nira.gov.so/hubiye','official']]},
  {id:'n41',theme:'sec',region:'Asia-Pacific',country:'india',sector:'Health',type:'News',trust:'media',sources:2,date:'31 Oct 2026',
   title:'Tripura says all its government hospitals are now on one digital health system',
   summary:'Health Secretary Kiran Gitte said on 31 October that 100% of government hospitals in the Indian state of Tripura are onboarded to its Integrated Health Management Information System (IHMIS), meeting the 31 October target he set in August. IHMIS covers outpatient registration and tokens, admission and discharge, prescriptions and pharmacy, and lab reports sent to patients’ phones. Records are to be linked through each patient’s Ayushman Bharat Health Account (ABHA) number so that referrals between hospitals carry the patient’s history. The number of records already linked to ABHA was not disclosed; getting doctors to use the system every day is the next step.',
   why:'Onboarding hospitals is the easy part; daily use by clinicians and linking records to a national health ID decide whether a digital record actually follows the patient.',
   links:[['Tripura IHMIS: all government hospitals go digital','Elets eHealth','https://ehealth.eletsonline.com/2026/11/tripura-ihmis-paperless-government-hospitals/','media'],['Tripura’s health services to be fully digitalised by Oct 31: official','ETV Bharat','https://www.etvbharat.com/en/state/tripura-health-services-to-be-fully-digitalised-by-oct-31-official-enn26081108376','media']]},
  {id:'n40',theme:'sec',region:'Europe',country:'',sector:'Health',type:'Report',trust:'official',sources:1,date:'30 Oct 2026',
   title:'WHO/Europe reports on four years of its digital health action plan, including a first regional review of AI for health',
   summary:'WHO’s Regional Office for Europe published its biennial progress report on the Regional digital health action plan 2023–2030, covering June 2024 to March 2026. WHO says it helped 20 countries strengthen health data collection and use, supported national digital health strategies in Albania, Armenia, Bulgaria, Latvia, North Macedonia and Spain, helped Bosnia and Herzegovina bring telemedicine into primary care, and worked with Georgia, Tajikistan and Uzbekistan on interoperability. It also issued a first report on AI for health in the region and the EU, and an analysis finding that equity is applied inconsistently in digital health practice. A member-state working group is feeding into a regional roadmap for AI in health for 2026–2033 and the next global digital health strategy for 2028–2033.',
   why:'WHO’s own conclusion that more must be done on digital literacy and access for patients and health workers is a lesson for every country building national health records.',
   links:[['Four years of the Regional digital health action plan: what WHO and countries have achieved','WHO Regional Office for Europe','https://www.who.int/europe/news/item/30-10-2026-four-years-of-the-regional-digital-health-action-plan--what-who-and-countries-have-achieved','official']]},
  {id:'n39',theme:'dpi',region:'Americas',country:'',sector:'Social protection',type:'News',trust:'media',sources:2,date:'27–30 Oct 2026',
   title:'Jamaica to require national ID registration for hurricane relief; opposition calls it coercion',
   summary:'At a Hurricane Melissa press briefing on 27 October, Prime Minister Andrew Holness said everyone seeking recovery benefits, including grants, must register with the National Identification System (NIDS), calling it indispensable because Jamaica lacks a database that uniquely identifies citizens. On 30 October opposition justice spokesperson Zuleika Jess called the plan “completely unacceptable”, saying it turns a voluntary ID into a compulsory one through economic pressure and goes against the spirit of the 2019 court ruling that struck down the original NIDS law. She said thousands of people assessed and verified after the October 2025 hurricane are still waiting for aid.',
   why:'Tying emergency aid to ID enrolment can speed payments and cut duplication, but it can also exclude the people most in need; Nepal reversed a similar requirement for social security benefits in 2024.',
   links:[['“Unacceptable”: opposition against tying Hurricane Melissa relief assistance to NIDS registration','The Gleaner','https://jamaica-gleaner.com/article/news/20261030/unacceptableopposition-agaisnt-tying-hurricane-melissa-relief-assistance-nids','media'],['Jamaica opposition slams gov’t plan to require national ID for disaster relief',BU,'https://www.biometricupdate.com/202611/jamaica-opposition-slams-govt-plan-to-require-national-id-for-disaster-relief','media']]},
  {id:'n42',theme:'sec',region:'Africa',country:'',sector:'Agriculture',type:'News',trust:'media',sources:2,date:'26 Oct 2026',
   title:'Nigerian bank FCMB and Mastercard launch AgroPass to link smallholders with buyers, inputs and credit',
   summary:'First City Monument Bank (FCMB) and Mastercard launched AgroPass in Lagos, a digital platform developed by Mastercard that connects smallholder farmers with input suppliers, buyers, lenders and agribusinesses and builds a digital record of their business activity. FCMB said it provided ₦364.6 billion (about $236 million) in agricultural financing last year and supported more than 196,000 smallholder farmers. The bank uses a value-chain financing model that also covers seed companies, processors, distributors and exporters.',
   why:'A digital trading record can give farmers without collateral a credit history; how private platforms like this connect with the single national farmers register Nigeria’s agriculture ministry is pushing for will matter for scale.',
   links:[['FCMB, Mastercard launch digital platform to expand financing for farmers','Blueprint','https://blueprint.ng/?p=856878','media'],['FCMB and Mastercard launch AgroPass to expand finance access for Nigerian farmers','TechAfrica News','https://techafricanews.com/2026/11/02/fcmb-mastercard-launch-agropass-expand-finance-access-nigerian-farmers','media']]},
  {id:'n25',theme:'dpi',region:'Asia-Pacific',country:'bangladesh',sector:'Fintech & payments',type:'News',trust:'media',sources:2,date:'1 Nov 2026',
   title:'Bangladesh opens person-to-person payments by Bangla QR across banks and wallets',
   summary:'From 1 November 2026, people in Bangladesh can send money to another person by scanning that person’s Bangla QR code in any bank or mobile financial service app, without typing a phone or account number, Bangladesh Bank said in a press release. The service extends the national QR standard, which became mandatory for all merchants on 1 July and now works at about 39 lakh merchant points, to transfers between individuals across banks and wallets. Fees and transaction limits were not announced at launch.',
   why:'QR-based person-to-person transfers are how UPI and Pix became everyday tools; their success in Bangladesh will depend on whether fees stay below the 0.85% cap on MFS-originated transfers.',
   links:[['Bangladesh Bank launches QR-based P2P payment service','The Business Standard','https://www.tbsnews.net/economy/banking/bangladesh-bank-launches-qr-based-p2p-payment-service-1589731','media'],['Bangladesh Bank launches QR code-based person-to-person payment service','Daily Waadaa','https://www.dailywaadaa.com/business/2026/11/01/bangladesh-bank-launches-qr-code-based-person-to-person-payment-service','media']]},
  {id:'n19',theme:'dpi',region:'Africa',country:'',sector:'Fintech & payments',type:'Policy or law',trust:'media',sources:2,date:'2 Nov 2026',
   title:'West Africa makes mobile money interoperable through one instant payment system and doubles wallet limits',
   summary:'From 2 November 2026, new rules from the Central Bank of West African States (BCEAO) apply across the eight WAEMU countries. Instruction no. 020, signed on 8 October, requires interoperable person-to-person transfers to run through the BCEAO’s PI-SPI instant payment system, which already links more than 175 institutions and over 38 million users. Transfers are free up to CFAF 8,000 a day per user, with fees capped at 0.8% above that, and receiving money stays free. The maximum balance for an identified customer doubles from CFAF 2 million to CFAF 4 million, the monthly top-up ceiling rises from CFAF 10 million to CFAF 15 million, and issuers must keep 65% of customer funds in demand deposits, down from 75%.',
   why:'A regional central bank is using a public instant payment switch to end closed mobile money networks, one of the clearest cases of payments being run as digital public infrastructure.',
   links:[['The end of closed mobile money networks in West Africa','TechAfrica News','https://techafricanews.com/2026/10/26/89825/','media'],['BCEAO eases mobile money rules, gives operators more freedom to invest customer funds','Ecofin Agency','https://www.ecofinagency.com/news-finances/1210-59674-bceao-eases-mobile-money-rules-gives-operators-more-freedom-to-invest-customer-funds','media']]},
  {id:'n20',theme:'sec',region:'Africa',country:'',sector:'Health',type:'Policy or law',trust:'official',sources:2,date:'22 Oct 2026',
   title:'African Union member states validate the first continental framework for governing health data',
   summary:'Meeting in Addis Ababa, AU member states validated the African Continental Health Data Governance Framework, developed by Africa CDC with Transform Health through consultations since 2025. It sets common rules for lawful, secure and ethical use of health data and proposes a federated model, so countries can share data across borders for disease surveillance and care while keeping control of their national systems. It builds on the Malabo Convention, the AU Data Policy Framework and the Digital Transformation Strategy for Africa. Africa CDC will now finalise the text, which is expected to go through AU policy processes in 2027.',
   why:'Cross-border health data sharing in Africa has stalled on trust and sovereignty concerns; a shared framework gives ministries a common baseline for national health data laws.',
   links:[['AU member states validate African Continental Health Data Governance Framework','Africa CDC','https://africacdc.org/news-item/au-member-states-validate-african-continental-health-data-governance-framework/','official'],['AU member states validate African Continental Health Data Governance Framework','allAfrica','https://allafrica.com/stories/202610230017.html','media']]},
  {id:'n21',theme:'sec',region:'Asia-Pacific',country:'bangladesh',sector:'Health',type:'News',trust:'media',sources:1,date:'18 Oct 2026',
   title:'Bangladesh unveils a digital health push built on an e-health card and a national health database',
   summary:'At an event in Dhaka organised with the World Health Organization, State Minister for Health and Family Welfare Dr M A Muhit set out plans for a universal electronic health card and a national health database for nearly 200 million people. The database would link consultations, prescriptions, medicine purchases and test results. Plans also include app-based appointment booking, digital tracking of medicines supplied to public hospitals to curb illegal sales, and a national e-Hackathon. No budget or rollout timetable was announced.',
   why:'A shared health record linked to a national card would be the backbone for e-prescriptions and referrals; the missing timetable and budget will decide whether it moves beyond announcements.',
   links:[['From paper prescriptions to digital care: a new hope for Bangladesh','The Daily Star','https://www.thedailystar.net/health/news/paper-prescriptions-digital-care-new-hope-bangladesh-4306636','media']]},
  {id:'n22',theme:'ai',region:'Europe',country:'',sector:'Fintech & payments',type:'Guidance',trust:'official',sources:2,date:'19 Oct 2026',
   title:'UK financial regulator sets out good and poor practice for firms using AI, including agentic tools',
   summary:'The Financial Conduct Authority published examples of good practice and areas for improvement in how financial firms use machine learning, generative AI and agentic AI, drawn from its 2026 supervisory testing. It creates no new rules: existing rules, including the Consumer Duty and senior managers’ accountability, still apply. Good practice includes independent panels that challenge AI use cases and named senior owners for each one. Weak practice includes deploying AI before governance is in place and treating human review as a fix for flawed systems. The FCA also plans a framework for “agentic finance” covering agent identity and delegated authority.',
   why:'Regulators elsewhere are watching how the FCA supervises AI under existing law rather than new AI-specific rules; the approach offers a template for central banks and financial regulators in emerging markets.',
   links:[['AI in financial services: good practice and areas for improvement','Financial Conduct Authority','https://www.fca.org.uk/publications/good-poor-practice/ai-financial-services','official'],['FCA publishes AI good and poor practice for financial firms','The Paypers','https://thepaypers.com/regulations/news/fca-publishes-ai-good-and-poor-practice-for-financial-firms','media']]},
  {id:'n23',theme:'sec',region:'Americas',country:'',sector:'Education',type:'News',trust:'media',sources:1,date:'23 Oct 2026',
   title:'New York City lists 38 ed-tech products caught by its ban on student-facing AI in public schools',
   summary:'Chalkbeat obtained the list of 38 previously approved products whose generative AI features New York City public schools must switch off or drop under restrictions announced by Mayor Zohran Mamdani. It covers widely used reading and maths programmes, assessment tools and the education department’s own chatbot teaching assistant. The AI reading tutor Amira, used in more than 200 schools, was banned outright, and Google’s Gemini is being turned off for students. Some vendors dispute that their tools use generative AI; the department is reviewing products case by case, with a carve-out for tools that help English language learners.',
   why:'The largest US school system is showing how hard it is to regulate AI inside ed-tech procurement when vendors’ definitions of AI differ; education ministries face the same vetting problem.',
   links:[['NYC school AI ban: see 38 ed tech products officials say violate the policy','Chalkbeat','https://www.chalkbeat.org/newyork/2026/10/23/nyc-schools-ai-ban-list-38-education-technology-products/','media']]},
  {id:'n24',theme:'sec',region:'Asia-Pacific',country:'india',sector:'Education',type:'News',trust:'media',sources:1,date:'22–31 Oct 2026',
   title:'Himachal Pradesh puts every government school teacher on a digital profile with an AI skills baseline',
   summary:'India’s Himachal Pradesh signed an agreement on 22 October with Bharti Airtel Foundation to use its free Teacher App across government schools. On 31 October the Directorate of School Education told district officials to make sure all teachers and heads of schools register and complete a baseline survey of their digital and AI skills. The results will steer needs-based training, including AI Samarth Level 1 and 2 courses and an “AI Tools in Teaching” kit, in place of one-size-fits-all workshops.',
   why:'Mapping teachers’ digital skills before rolling out AI in classrooms is a step many education systems skip; a state-wide baseline lets training budgets follow actual gaps.',
   links:[['Himachal Pradesh puts every government school teacher on The Teacher App','Elets digitalLEARNING','https://digitallearning.eletsonline.com/2026/11/himachal-pradesh-the-teacher-app-bharti-airtel-foundation-teacher-digital-profiles-ai-training','media']]},
  {id:'n15',theme:'cyb',region:'Europe',country:'',sector:'Government',type:'News',trust:'media',sources:2,date:'27–29 Oct 2026',
   title:'Moldova takes 82 e-services offline after attackers extract data linked to 750,000 ID numbers',
   summary:'Moldova’s Electronic Governance Agency (AGE) said attackers exploited government e-services that needed no login between 19 and 23 October, querying about one million personal identification numbers (IDNPs) and extracting data linked to about 750,000 of them. Exposed fields include family links, health insurance status, benefits and pensions, driving licences, photographs, bank account numbers (IBANs) and tax debts; bank card data and state registers were not affected. As a precaution, 82 public services and more than 30 information systems were disconnected. Prime Minister Vasile Tofan said foreign state involvement is being examined, and AGE director Nicoleta Colomeeț is stepping down, with Artiom Cociu leading the agency on an interim basis.',
   why:'Unauthenticated services that query interconnected registries can turn a data exchange layer into a single point of mass exposure; it is a warning for every country building once-only services.',
   links:[['Moldova investigates possible foreign involvement in cyberattacks','The Record','https://therecord.media/moldova-investigates-possible-foreign-involvement-cyberattacks','media'],['Moldova e-government chief resigns after hack exposed data tied to 750,000 ID numbers','ID Tech','https://idtechwire.com/moldova-e-government-chief-resigns-after-hack-exposed-data-tied-to-750000-id-numbers/','media']]},
  {id:'n16',theme:'cyb',region:'Europe',country:'',sector:'Government',type:'News',trust:'media',sources:2,date:'28–29 Oct 2026',
   title:'Cyberattack takes Belgium’s MyMinfin tax portal offline; filing deadline moved to 16 November',
   summary:'Belgium’s Federal Public Service Finance took MyMinfin, Tax-on-web and Biztax offline as a precaution after intruders entered its systems overnight on 27–28 October and tried to alter parts of its digital environment. The ministry says the intrusion was contained within hours and that no data was leaked. Returns due on 31 October can now be filed until 16 November 2026. Federal police and the Centre for Cybersecurity Belgium are investigating.',
   why:'When a single tax portal goes down days before a deadline, the whole filing calendar moves; resilience and recovery planning matter as much as prevention for core e-services.',
   links:[['Cyberattack disrupts Belgian tax services before deadline','The Record','https://therecord.media/cyberattack-disrupts-belgian-tax-services-before-deadline','media'],['No data leaked in Finance Ministry cyberattack, services still down','The Brussels Times','https://brusselstimes.com/2383490/no-data-leaked-in-finance-ministry-cyberattack-services-still-down','media']]},
  {id:'n17',theme:'dpi',region:'Europe',country:'',sector:'Government',type:'Policy or law',trust:'media',sources:2,date:'27 Oct 2026',
   title:'Türkiye plans a digital ID wallet prototype in 2027 and sets e-Devlet growth targets',
   summary:'Türkiye’s 2027 Presidential Annual Program, published in the Official Gazette on 27 October, plans a national digital ID wallet prototype in 2027, led by the Cybersecurity Presidency with the Ministry of Interior. It would first hold basic identity documents and diplomas, piloted with a university and prioritising public employees. The programme targets at least 71 million e-Devlet users, about 10,000 services and 7,500 mobile services in 2027, up from 9,436 services from 1,130 institutions in September 2026. Separately, from 1 November social media platforms may not open accounts for children under 15, with ages checked through an e-Devlet age token.',
   why:'Türkiye is pairing a mature e-government portal with a wallet and privacy-preserving age checks, a combination many countries outside the EU are now weighing.',
   links:[['Türkiye plans digital ID wallet pilot for 2027 as age verification expands',BU,'https://www.biometricupdate.com/202610/turkiye-plans-digital-id-wallet-pilot-for-2027-as-age-verification-expands','media'],['Dijital kimlik cüzdanı için tarih belli oldu (Anadolu Agency report)','İstiklal','https://www.istiklal.com.tr/genel/dijital-kimlik-cuzdani-icin-tarih-belli-oldu-1109426h','media']]},
  {id:'n18',theme:'pol',region:'Americas',country:'brazil',sector:'Telecom',type:'Policy or law',trust:'media',sources:2,date:'28 Oct 2026',
   title:'Brazil’s telecom regulator makes face biometrics mandatory to activate and keep mobile lines',
   summary:'Anatel issued Technical Norm GT-SEG.2026.11, drafted by a fraud and scams subgroup, requiring all mobile operators, including MVNOs, to verify individual customers with a face check and liveness detection at ISO/IEC 30107-3 level 2 or higher. Deadlines are 30 September 2027 for new prepaid lines, 31 December 2027 for postpaid activations, portability and SIM swaps, and 31 December 2028 for existing customers. From January 2029, unvalidated lines face a 120-day suspension, with emergency calls preserved, and then cancellation.',
   why:'It ties the right to a phone line to biometric verification for millions of people, raising inclusion and data protection questions that other regulators fighting SIM fraud will face too.',
   links:[['Brazil’s Anatel makes facial biometric checks mandatory for mobile lines','ID Tech','https://idtechwire.com/brazils-anatel-makes-facial-biometric-checks-mandatory-for-mobile-lines/','media'],['Anatel vai exigir biometria para manter número de telefone no Brasil','Canaltech','https://canaltech.com.br/seguranca/anatel-vai-exigir-biometria-para-manter-numero-de-telefone-no-brasil/','media']]},
  {id:'n1',theme:'ai',region:'Europe',country:'',sector:'Government',type:'Policy or law',trust:'official',sources:2,date:'27 Jul 2026 · deadline 2 Dec 2026',
   title:'EU delays high-risk AI Act rules; two new bans apply from 2 December',
   summary:'The EU’s "Digital Omnibus on AI" (Regulation 2026/1744) entered into force on 27 July 2026. It moves the AI Act’s high-risk obligations for Annex III uses, such as employment, credit, education and biometrics, from August 2026 to 2 December 2027. Obligations for AI in regulated products move to 2 August 2028. Two new prohibitions, on non-consensual intimate deepfakes and child sexual abuse material, apply from 2 December 2026.',
   why:'Public bodies that deploy AI in the EU, and suppliers selling to them, get more time for high-risk compliance, but the transparency and new prohibition deadlines this December still stand.',
   links:[['AI Act: obligations in force and delays under omnibus 2026/1744','ActuIA','https://www.actuia.com/en/news/ai-act-obligations-in-force-and-delays-under-omnibus-2026-1744/','media'],['EU AI Act Omnibus Agreement: postponed high-risk deadlines','Gibson Dunn','https://www.gibsondunn.com/eu-ai-act-omnibus-agreement-postponed-high-risk-deadlines-and-other-key-changes/','expert']]},
  {id:'n2',theme:'dpi',region:'Africa',country:'',sector:'Government',type:'Report',trust:'expert',sources:1,date:'13 Oct 2026',
   title:'CIPESA report warns DPI is reshaping state–citizen relations in 11 African countries',
   summary:'The State of Internet Freedom in Africa 2026 report by CIPESA, launched at FIFAfrica26 in Mauritius, reviews digital public infrastructure in Egypt, Ethiopia, Ghana, Kenya, Nigeria, Senegal, South Africa, Tunisia, Uganda, Zambia and Zimbabwe. It finds that design flaws, technical failures and inaccurate records in foundational ID and mandatory digital gateways often exclude vulnerable groups.',
   why:'It adds African evidence to the case for rights-respecting DPI safeguards before systems become entrenched, a priority for donors funding ID and registry programmes.',
   links:[['Digital public infrastructure reshaping state-citizen relations in Africa, report warns',BU,'https://www.biometricupdate.com/202610/digital-public-infrastructure-reshaping-state-citizen-relations-in-africa-report-warns','media']]},
  {id:'n3',theme:'dpi',region:'Africa',country:'rwanda',sector:'Government',type:'News',trust:'media',sources:2,date:'12 Oct 2026',
   title:'Rwanda approves $19m more World Bank financing for digital ID and CRVS',
   summary:'Rwandan lawmakers ratified about US$19 million in additional IDA financing for the Rwanda Digital Acceleration Project. The State Minister reported the digital ID rollout as 76% complete and CRVS digitisation as 89% complete; the National Identification Agency reported about 13.7 million people biometrically enrolled as of 4 October. The project’s closing date moves to June 2028.',
   why:'Rwanda is one of the few countries building a single digital ID together with digitised civil registration, a model many governments are watching.',
   links:[['New World Bank funding to support Rwanda’s digital ID rollout, CRVS digitization',BU,'https://www.biometricupdate.com/202610/new-world-bank-funding-to-support-rwandas-digital-id-rollout-crvs-digitization','media'],['Rwanda secures €17 million World Bank loan to expand digital identity and cybersecurity infrastructure','TechInAfrica','https://www.techinafrica.com/?p=42230','media']]},
  {id:'n4',theme:'dpi',region:'Asia-Pacific',country:'pakistan',sector:'Government',type:'News',trust:'media',sources:2,date:'29 Oct 2026',
   title:'Pakistan selects 10 public services for digital delivery under World Bank-backed DEEP',
   summary:'Pakistan’s US$78 million Digital Economy Enhancement Project, overseen by NITB and NADRA, has chosen 10 priority services for digital delivery and linked single sign-on to the National Data Exchange Layer. NADRA’s PakID Vault in the Pak App now holds six official documents, including the CNIC.',
   why:'It shows a country joining digital ID, a data exchange layer and service delivery in one programme, the core DPI pattern.',
   links:[['Pakistan advances digital ID infrastructure, selects 10 services for DEEP rollout',BU,'https://www.biometricupdate.com/202610/pakistan-advances-digital-id-infrastructure-selects-10-services-for-deep-rollout','media'],['Digital economy enhancement: World Bank flags implementation gaps in USD69.16m project (9 Sep 2026)','Business Recorder','https://www.brecorder.com/news/40438591/digital-economy-enhancement-world-bank-flags-implementation-gaps-in-usd6916m-project','media']]},
  {id:'n5',theme:'pol',region:'Asia-Pacific',country:'india',sector:'Government',type:'Policy or law',trust:'official',sources:1,date:'Takes effect 13 Nov 2026',
   title:'India’s Consent Manager rules under the DPDP framework take effect on 13 November',
   summary:'Under the Digital Personal Data Protection Rules notified on 13 November 2025, Rule 4 on registering and running Consent Managers takes effect on 13 November 2026. The main obligations on data fiduciaries, including consent, notices, security safeguards and breach notification, follow on 13 May 2027.',
   why:'Consent Managers are India’s answer to user-controlled data sharing and a reference point for other countries designing consent layers.',
   links:[['DPDP Act and Rules 2025: the 2026 compliance milestones','Mondaq','https://www.mondaq.com/dpdp-act-and-rules-2025-the-2026-compliance-milestones-businesses-cant-afford-to-miss/1830402','media']]},
  {id:'n6',theme:'ai',region:'Americas',country:'',sector:'Government',type:'Policy or law',trust:'expert',sources:1,date:'20 Oct 2026',
   title:'Panama sets out a 10-year national AI strategy built on five pillars',
   summary:'Panama’s National Artificial Intelligence Strategy, announced in July and developed by SENACYT with Georgia Tech, rests on five pillars: governance and regulation, talent and institutional capacity, data and infrastructure, ethics and inclusion, and international cooperation. Its design drew on a national survey with more than 6,700 respondents.',
   why:'A structured, consultative strategy from a smaller economy is a useful template for countries drafting their first AI strategy.',
   links:[['Georgia Tech partners with Panama to chart national AI strategy','Georgia Tech Research','https://news.research.gatech.edu/2026/10/20/georgia-tech-partners-panama-chart-national-ai-strategy','expert']]},
  {id:'n7',theme:'cyb',region:'Global',country:'',sector:'Government',type:'Report',trust:'media',sources:1,date:'22 Oct 2026',
   title:'Intrusion attempts on state and local government networks up 242%, vendor data shows',
   summary:'SonicWall data for the first half of 2026 shows a 242% year-on-year rise in intrusion attempts against state and local government networks, with web application attacks making up 85.1% of the activity. Malware detections rose 8.6%, while ransomware activity fell 74%. SonicWall links the rise to outdated technology, limited staff and patchy software updates.',
   why:'Local governments run many citizen-facing services on ageing systems; the figures support funding for patching and staffing, not only new systems.',
   links:[['State and local government cyberattacks rose 242 percent in first half of 2026','Security Today','https://securitytoday.com/articles/2026/10/22/research-state-and-local-government-cyberattacks-rose-242-percent-in-first-half-of-2026.aspx','media']]},
  {id:'n8',theme:'ai',region:'Europe',country:'',sector:'Government',type:'News',trust:'media',sources:1,date:'28 Oct 2026',
   title:'UK Budget funds a £40m unit to detect AI systems that slip their controls',
   summary:'The UK Budget of 28 October 2026 includes £40 million for a National Agentic Security Unit to detect and respond to AI systems that go beyond their intended controls, and £24 million for cyber defence in hospitals, schools and councils, according to reports citing City AM.',
   why:'It is one of the first government units aimed specifically at agentic AI risk, alongside new money for public-sector cyber defence.',
   links:[['Budget 2026 funds £40m unit to monitor rogue AI agents','Resultsense','https://www.resultsense.com/news/2026-10-29-budget-national-agentic-security-unit/','media']]},
  {id:'n9',theme:'dpi',region:'Europe',country:'',sector:'Government',type:'Policy or law',trust:'media',sources:1,date:'29 Oct 2026',
   title:'Italy’s privacy regulator approves the national plan for its EU digital identity wallet',
   summary:'Italy’s data protection authority, the Garante, approved the technical and architectural plan for the IT-Wallet, Italy’s implementation of the EU Digital Identity Wallet, without requesting changes. It set conditions on handling data subject rights, safeguards for biometric data and demonstrable risk management.',
   why:'EU wallets must launch soon; Italy’s review shows what regulators expect from wallet architectures.',
   links:[['Italian data protection regulator approves national digital ID wallet plan',BU,'https://www.biometricupdate.com/202610/italian-data-protection-regulator-approves-national-digital-id-wallet-plan','media']]},
  {id:'n10',theme:'sec',region:'Asia-Pacific',country:'india',sector:'Agriculture',type:'News',trust:'media',sources:1,date:'26 Oct 2026',
   title:'India issues 110 million Farmer IDs under its Digital Agriculture Mission',
   summary:'India has created 11 crore (110 million) unique Farmer IDs under the Digital Agriculture Mission of the Ministry of Agriculture and Farmers’ Welfare, five months ahead of its 31 March 2027 deadline.',
   why:'Farmer registries are becoming the base layer for subsidies, credit and advisory services in agriculture-heavy economies.',
   links:[['Farmer ID: 11 crore digital IDs under Digital Agriculture Mission','NEXT IAS','https://www.nextias.com/ca/current-affairs/26-10-2026/farmer-id-digital-agriculture-mission','media']]},
  {id:'n11',theme:'sec',region:'Africa',country:'',sector:'Agriculture',type:'News',trust:'media',sources:1,date:'30 Aug 2026',
   title:'Lesotho launches a national farmer registry built on a GovStack specification',
   summary:'Lesotho’s Ministry of Agriculture, Food Security and Nutrition launched the Lesotho Farmers Portal, its first national registry combining farmer and land data. Farmers are registered against their national ID number and land parcels with GPS boundaries, using the GovStack Registration Building Block specification with support from ITU and WFP.',
   why:'A practical example of reusable DPI building blocks applied in a small country’s agriculture sector.',
   links:[['Lesotho launches National Farmers Portal','PR Newswire','https://www.prnewswire.com/news-releases/lesotho-launches-national-farmers-portal-giving-every-farmer-a-place-in-a-single-digital-registry-302864372.html','media']]},
  {id:'n12',theme:'dpi',region:'Africa',country:'',sector:'Government',type:'News',trust:'media',sources:1,date:'14 Oct 2026',
   title:'Benin moves biometric ID card renewals online',
   summary:'Benin’s identification agency ANIP now lets citizens apply for and track renewals of the national biometric ID card online, around the clock. Applications are still validated manually and cards are usually collected in person. Enrolment reportedly covers nearly 99% of the population.',
   why:'Moving ID services online is a common next step once enrolment is near-universal.',
   links:[['Benin moves biometric national ID card renewals online',BU,'https://www.biometricupdate.com/202610/benin-moves-biometric-national-id-card-renewals-online','media']]},
  {id:'n13',theme:'egov',region:'Asia-Pacific',country:'india',sector:'Government',type:'News',trust:'expert',sources:1,date:'28 Oct 2026',
   title:'Digital Citizen Summit in Hyderabad debates making India’s DPI more accountable',
   summary:'IIIT Hyderabad hosted the Digital Citizen Summit regional dialogue on digital public infrastructure for governance, organised with the Digital Empowerment Foundation and Code for Good Tech. Participants discussed how to make DPI such as Aadhaar, UPI and DigiLocker more inclusive, accountable and accessible.',
   why:'Civil society scrutiny of India’s DPI matters globally because the model is being promoted abroad.',
   links:[['IIIT Hyderabad hosts Digital Citizen Summit','IIIT Hyderabad','https://www.iiit.ac.in/iiit-hyderabad-hosts-digital-citizen-summit/','expert']]},
  {id:'n14',theme:'sec',region:'Asia-Pacific',country:'',sector:'Health',type:'News',trust:'official',sources:1,date:'15 May 2026',
   title:'Cambodia rolls out a national health information system on DHIS2',
   summary:'Cambodia’s Ministry of Health launched a new electronic Health Management Information System on the DHIS2 platform, to be rolled out in all 25 provinces with support from WHO, UNICEF, CHAI and Gavi.',
   why:'DHIS2, a digital public good, is the backbone of health data in many lower-income countries.',
   links:[['Cambodia launches digital health information system','WHO Cambodia','https://www.who.int/cambodia/news/detail/15-05-2026-cambodia-launches-digital-health-information-system-to-strengthen-decision-making-nationwide','official']]},
  {id:'n26',theme:'pol',region:'Africa',country:'uganda',sector:'Government',type:'Policy or law',trust:'media',sources:2,date:'21 Oct 2026',
   title:'Uganda launches a five-year National Data Strategy costed at UGX 1.66 trillion',
   summary:'Uganda’s Ministry of ICT and National Guidance launched the National Data Strategy for 2026/27–2030/31, developed with UNDP and UN Global Pulse. It aims to raise the number of government platforms integrated through the UGhub data exchange from 135 to 300, raise the share of national plan indicators backed by verifiable data from 36% to 80%, and build two Tier IV data centres with 10 petabytes of sovereign storage. The plan is costed at UGX 1,662.6 billion over five years. MPs at the launch asked how data hosted abroad will be protected and called for cutting the 10% import duty on entry-level devices.',
   why:'A costed, targeted data strategy is rare in the region; its test will be whether annual budgets fund it.',
   links:[['Uganda targets 300 integrated government platforms under new data strategy','allAfrica','https://allafrica.com/stories/202610220526.html','media'],['Uganda launches UGX 1.663 trillion National Data Strategy','Uganda Broadcasting Corporation','https://ubc.go.ug/2026/10/20/uganda-launches-ugx-1-663-trillion-national-data-strategy-to-drive-digital-economy-and-public-planning','media']]},
  {id:'n27',theme:'sec',region:'Americas',country:'',sector:'Agriculture',type:'News',trust:'official',sources:1,date:'24 Oct 2026',
   title:'NASA and the US Department of Agriculture agree to use satellite data in crop estimates',
   summary:'NASA and the US Department of Agriculture signed a memorandum of understanding on 24 October 2026 to apply Earth observation data, geospatial analytics and modelling to crop monitoring, acreage and yield estimates and drought assessment. It forms part of USDA’s plan to modernise its agricultural data systems.',
   why:'Official crop statistics move world prices; better use of satellite data is a model for statistics offices elsewhere.',
   links:[['NASA, USDA sign agreement advancing Earth science, agriculture','NASA','https://www.nasa.gov/news-release/nasa-usda-sign-agreement-advancing-earth-science-agriculture/','official']]},
  {id:'n28',theme:'ai',region:'Africa',country:'uganda',sector:'Government',type:'News',trust:'media',sources:1,date:'15 Oct 2026',
   title:'Uganda and Korea’s aid agency explore AI cooperation, including translation of government information',
   summary:'Uganda’s ICT Permanent Secretary Dr Aminah Zawedde met a KOICA delegation to discuss cooperation on AI, digital infrastructure, ICT skills and digital government services. Ideas included using AI to translate government information into local languages and digital tools for the Parish Development Model. The talks were exploratory, with no projects or funding announced.',
   why:'Local-language AI could widen access to public information in a country with many languages.',
   links:[['Uganda and South Korea explore AI and digital transformation partnership','TechAfrica News','https://techafricanews.com/2026/10/15/uganda-south-korea-ai-digital-transformation-partnership/','media']]},
  {id:'n29',theme:'sec',region:'Africa',country:'uganda',sector:'Fintech & payments',type:'Data',trust:'media',sources:1,date:'9 Oct 2026',
   title:'Uganda’s mobile money flows reach UGX 263 trillion in seven months',
   summary:'Mobile money transactions in Uganda were worth UGX 263 trillion in January–July 2026, 72% of the full-year 2025 total of UGX 365.9 trillion, according to Bank of Uganda data. First-half value rose 32.5%. Active customers reached 38 million in July 2026 and agents 1.3 million.',
   why:'Mobile money is the most used digital service in Uganda; any disruption, such as an internet shutdown, hits it first.',
   links:[['Mobile money value reaches 72 per cent of 2025 total','UG Business','https://ugbusiness.com/2026/10/digital-economy/mobile-money-value-reaches-72-per-cent-of-2025-total','media']]},
  {id:'n30',theme:'sec',region:'Africa',country:'',sector:'Agriculture',type:'News',trust:'media',sources:2,date:'30 Sep 2026',
   title:'Nigeria’s agriculture minister calls for one national digital farmers register anchored on the NIN',
   summary:'At a national dialogue in Abuja, Agriculture Minister Abubakar Kyari proposed a single national digital farmers register built on existing work with the National Identity Management Commission, IFAD and FAO. States would enumerate and verify farmers; the federal ministry would set one interoperable standard. The aim is to target fertiliser, loans and other support to genuine farmers and support export traceability. No registration total was given.',
   why:'Nigeria’s attempt to merge duplicate farmer databases is a test case for agriculture registries across Africa.',
   links:[['Kyari pushes national digital farmers register to eliminate duplication','The Authority','https://authorityngr.com/2026/09/30/kyari-pushes-national-digital-farmers-register-to-eliminate-duplication/','media'],['Nigeria launches National Digital Farmers Registry to strengthen food security','Federal Ministry of Agriculture and Food Security','https://agriculture.gov.ng/nigeria-launches-national-digital-farmers-registry-to-strengthen-food-security/','official']]},
  {id:'n31',theme:'enb',region:'Africa',country:'uganda',sector:'Telecom',type:'News',trust:'media',sources:1,date:'1 Sep 2026',
   title:'Starlink residential service goes live in Uganda after a five-year licence',
   summary:'Starlink began taking residential orders in Uganda on 1 September 2026, after the Uganda Communications Commission granted a five-year operating licence in May. Conditions include a national gateway, a local office and local staff. Business resellers launched in late August. Starlink had disabled Ugandan terminals in January after a regulator directive before the election.',
   why:'Satellite broadband can reach areas fibre does not, but licence conditions keep it under national control.',
   links:[['Starlink is now live in Uganda','Space in Africa','https://spaceinafrica.com/2026/09/01/starlink-is-now-live-in-uganda/','media']]},
  {id:'n32',theme:'pol',region:'Africa',country:'uganda',sector:'Government',type:'News',trust:'media',sources:1,date:'19 Aug 2026',
   title:'Uganda’s data protection office says over 500,000 organisations process data without registering',
   summary:'Uganda’s Personal Data Protection Office says about 14,000 organisations have registered under the Data Protection and Privacy Act 2019, while more than 500,000 collect personal data without registering. Its director said unregistered processing is a criminal offence and that the office is working with police and prosecutors. He urged citizens to ask why businesses photocopy their national ID cards.',
   why:'Registration of data controllers is the first step of enforcement; the gap shows how far compliance still has to go.',
   links:[['Over 500,000 Ugandan firms collect personal data without registration','Eagle Online','https://eagle.co.ug/2026/08/19/over-500000-ugandan-firms-collect-personal-data-without-registration-pdpo/','media']]},
  {id:'n33',theme:'grn',region:'Europe',country:'',sector:'Agriculture',type:'Policy or law',trust:'official',sources:2,date:'13 Jul 2026',
   title:'EU updates the scope of its deforestation rules ahead of 30 December 2026 start',
   summary:'The European Commission adopted measures adjusting which products fall under the EU Deforestation Regulation and setting technical rules for its information system, including simplified declarations for micro and small primary operators. The regulation applies from 30 December 2026 to large and medium operators and from 30 June 2027 to other micro and small operators. Non-EU suppliers acting as operators must still provide plot-level geolocation.',
   why:'Exporters of cocoa, coffee, palm oil and other goods need farm-level traceability to keep EU market access.',
   links:[['Commission updates product scope and tools to support EUDR','European Commission','https://environment.ec.europa.eu/news/commission-updates-product-scope-and-tools-support-eudr-2026-07-13_en','official'],['EU Deforestation Regulation application postponed to 30 December 2026','EY Tax News','https://taxnews.ey.com/news/2026-0237-eu-deforestation-regulation-application-postponed-to-30-december-2026','expert']]},
  {id:'n34',theme:'sec',region:'Global',country:'',sector:'Agriculture',type:'Data',trust:'expert',sources:1,date:'18 Mar 2026',
   title:'Global agrifoodtech funding holds at US$16.2 billion, with money shifting to farms',
   summary:'AgFunder’s 2026 report counts US$16.2 billion of agrifoodtech venture funding in 2025, flat on 2024, with deal numbers down 12%. Upstream funding for farms and food production rose 7% to US$9 billion, climate technology in the sector recovered to US$3.9 billion and debt reached 18.2% of funding.',
   why:'Private capital is concentrating in deep technology; public registries and payments remain the main channel for smallholders.',
   links:[['Agrifoodtech funding is flat. The interesting part is where it isn’t','AgFunder News','https://agfundernews.com/agrifoodtech-funding-is-flat-the-interesting-part-is-where-it-isnt','expert']]},
  {id:'n35',theme:'ai',region:'Asia-Pacific',country:'india',sector:'Agriculture',type:'News',trust:'official',sources:1,date:'17 Feb 2026',
   title:'India launches Bharat-VISTAAR, an AI farm advisory service described as public infrastructure',
   summary:'India’s agriculture minister launched Bharat-VISTAAR in Jaipur. Farmers can get weather, market price, pest, soil and scheme information by phone helpline, chatbot or app, drawing on AgriStack, weather and market data. It launched in Hindi and English with plans for 11 languages within six months.',
   why:'Voice-first AI in local languages is how advisory services can reach farmers who do not read well or use apps.',
   links:[['AI farmer revolution to begin from Jaipur: Bharat-VISTAAR','Press Information Bureau','https://www.pib.gov.in/PressReleasePage.aspx?PRID=2228842&reg=3&lang=1','official']]},
  {id:'n36',theme:'dpi',region:'Africa',country:'uganda',sector:'Government',type:'News',trust:'media',sources:1,date:'9 Feb 2026',
   title:'Uganda’s national ID drive reaches 35 million people, but new registrations lag',
   summary:'Uganda’s registration authority NIRA closed the parish phase of its mass ID registration on 8 February 2026 with about 35 million people in the system. All 28.6 million legacy records were migrated and 90.5% of planned renewals completed, but only 37.3% of 17.2 million targeted new registrations were achieved, and 2.58 million of 7.26 million cards shipped to districts had been collected.',
   why:'Registration is only half the job; uncollected cards and missing newcomers limit what the ID can do.',
   links:[['35 million Ugandans registered in national ID drive','New Vision','https://www.newvision.co.ug/category/news/35-million-ugandans-registered-in-national-id-NV_227736_022026','media']]}
];
